import { icon, sprite } from './art.js';
import { characterSprite, characterPortrait } from './characters.js';
import { clockProjects, discoveries, discoveryProjects } from './clockwork-content.js';
import { neighbourUnlocked, lockReason, mechanismOrder, mechanismReady } from './neighbour-model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,id='')=>`<button class="button outline" data-neighbour="${action}" data-id="${id}">${label}</button>`;
const top=label=>`<div class="dialog-top"><span class="eyebrow">${label}</span><button class="icon-button" data-neighbour="close" aria-label="Close">${icon('close')}</button></div>`;
export function mechanismArt(p,working=false,prefix='bench'){
  const id=`${prefix}-${p.id}`;
  return `<svg viewBox="0 0 200 230" class="mechanism-art ${working?'mechanism-working':''}" aria-hidden="true"><defs><linearGradient id="${id}-wood" x2="1" y2="1"><stop stop-color="#ca9560"/><stop offset=".5" stop-color="#71442c"/><stop offset="1" stop-color="#b57c47"/></linearGradient><radialGradient id="${id}-brass"><stop stop-color="#ffe6a1"/><stop offset=".7" stop-color="#cc9d54"/><stop offset="1" stop-color="#74502e"/></radialGradient></defs>
    <ellipse cx="100" cy="218" rx="77" ry="8" fill="#2d241d" opacity=".35"/>
    ${p.object==='music'?`<path d="M27 92L100 68 176 93 174 197 101 215 27 192Z" fill="url(#${id}-wood)" stroke="#55321f" stroke-width="5"/><path d="M27 92L30 32 173 32 176 93Z" fill="#7d5439" stroke="#caa06a" stroke-width="5"/><path d="M43 45H158V80H43Z" fill="#4b5647" stroke="#dfba7d" stroke-width="2"/><ellipse cx="100" cy="94" rx="70" ry="22" fill="#47372a"/><g class="music-cylinder"><rect x="50" y="84" width="95" height="27" rx="13" fill="url(#${id}-brass)" stroke="#e3be78"/>${Array.from({length:10},(_,i)=>`<path d="M${57+i*9} 90v13" stroke="#6c512c" stroke-width="2"/>`).join('')}</g><path d="M45 115L143 117 133 145 53 142Z" fill="#d8bc79"/>${Array.from({length:8},(_,i)=>`<path d="M${57+i*10} 119v20" stroke="#695737" stroke-width="2"/>`).join('')}<rect x="91" y="169" width="18" height="20" rx="3" fill="url(#${id}-brass)"/><text class="music-note" x="150" y="54" fill="#ffdfa0" font-size="28">♪</text>`:
    `<path d="M36 207V66Q36 15 100 15Q164 15 164 66V207Z" fill="url(#${id}-wood)" stroke="#573923" stroke-width="6"/><path d="M45 201V67Q45 24 100 24Q155 24 155 67V201" fill="none" stroke="#d5aa70" stroke-width="2"/><rect x="25" y="202" width="150" height="12" rx="4" fill="#87532f" stroke="#d0a16a" stroke-width="3"/><circle cx="100" cy="83" r="49" fill="url(#${id}-brass)" stroke="#543e29" stroke-width="3"/><circle cx="100" cy="83" r="40" fill="#f4dfb1"/>${Array.from({length:12},(_,i)=>`<path d="M100 46v5" transform="rotate(${i*30} 100 83)" stroke="#715333" stroke-width="2"/>`).join('')}<path d="M100 83L79 71" stroke="#694b31" stroke-width="5" stroke-linecap="round"/><g class="clock-hand"><path d="M100 83V51" stroke="#694b31" stroke-width="3" stroke-linecap="round"/></g><circle cx="100" cy="83" r="4" fill="#a87f45"/><path d="M70 145Q100 130 130 145V190H70Z" fill="#433b2c" stroke="#ceaa6c" stroke-width="3"/><g class="clock-pendulum"><path d="M100 140v36" stroke="#d5b66d" stroke-width="3"/><circle cx="100" cy="180" r="11" fill="url(#${id}-brass)"/></g>`}</svg>`;
}
export function renderClockwork(state,pet){
  const done=clockProjects.filter(p=>state.neighbours.completed.includes(p.id)).length;
  return `<section class="neighbours-root neighbours-world" data-view="clockwork"><header class="court-heading"><div><p class="eyebrow">MIRA’S CLOCKMAKER WORKSHOP</p><h1>A little time, lovingly mended</h1><p>${done}/4 keepsakes working again. Every one belongs to someone.</p></div><a class="button outline" href="#village">Back to the village</a></header><div class="court-stage"><div class="court-frame clockwork-frame"><img class="neighbour-backdrop" src="assets/clockmaker-workshop.png" alt="Mira’s warm wooden workshop with brass parts, a green lamp and the village outside its window">${clockProjects.map((p,i)=>`<button class="workbench-object" style="left:${25+i*17}%" data-neighbour="project" data-id="${p.id}" aria-label="${esc(p.title)}: ${state.neighbours.completed.includes(p.id)?'repaired':neighbourUnlocked(state,p)?'ready to mend':lockReason(state,p)}">${mechanismArt(p,state.neighbours.completed.includes(p.id))}<span>${['Kitchen clock','Library dial','June’s music box','The village clocks'][i]}<small>${state.neighbours.completed.includes(p.id)?'Working again':neighbourUnlocked(state,p)?'Mira has saved you a place':'A later repair'}</small></span></button>`).join('')}
    <button class="clockmaker-mira" data-neighbour="clock-ledger" aria-label="Talk with Mira about the repairs">${characterSprite('mira')}<span>Mira’s repair ledger</span></button><span class="clockwork-player">${characterSprite('traveler','',state.wardrobe)}<span class="court-pet">${sprite(pet.id)}</span></span>${state.neighbours.completed.includes('discovery-key')?'<span class="returned-key" title="Orrin’s key, found with your companion" aria-label="Orrin’s returned key"><svg viewBox="0 0 28 60" width="100%" height="100%" aria-hidden="true"><circle cx="14" cy="12" r="8" fill="none" stroke="currentColor" stroke-width="4"/><path d="M14 20v32h9v-7h-9m0-8h7" fill="none" stroke="currentColor" stroke-width="4"/></svg></span>':''}<span class="court-lamplight" aria-hidden="true"></span></div></div><div class="neighbour-bottom"><p>Choose a keepsake on the bench. Listen, inspect, and mend it together.</p>${btn('clock-ledger','Read Mira’s repair ledger')}</div></section>`;
}
export function clockLedger(state){return `${top('MIRA · A WORKSHOP FULL OF MEMORIES')}<div class="apprentice-intro">${characterPortrait('mira','community-portrait')}<div><h2>Nothing loved is too small to mend.</h2><p>Orrin taught Mira that a repair begins by listening to the person who brought it. His old bench has room for your notebook now.</p></div></div><ol class="neighbour-project-list">${clockProjects.map(p=>`<li><span class="lesson-knot">${icon(state.neighbours.completed.includes(p.id)?'check':'clock')}</span><div><strong>${p.title}</strong><small>${state.neighbours.completed.includes(p.id)?p.outcome:neighbourUnlocked(state,p)?p.story:lockReason(state,p)}</small></div>${btn('project','Visit',p.id)}</li>`).join('')}</ol>${state.neighbours.completed.includes('discovery-key')?'<blockquote class="neighbour-memory">“You and your companion found the key I thought we had lost. Orrin would have liked that.”</blockquote>':''}`;}
export function inspectionMarkup(state,p){
  return `<section class="teaching-prompts"><h3>Listen to the mechanism</h3><p>${p.inspection}</p><div class="teaching-options">${p.choices.map((c,i)=>`<button data-neighbour="inspect" data-id="${p.id}" data-index="${i}" aria-pressed="${state.neighbours.inspected.includes(p.id)&&p.answer===i}">${esc(c)}</button>`).join('')}</div><p id="inspection-feedback" class="teaching-feedback" role="status">${state.neighbours.inspected.includes(p.id)?p.feedback[p.answer]:''}</p>${p.order?`<h3>Arrange the little jobs</h3><p>Move the functions into their working order. The game handles play_melody after your Python returns the finished notes.</p><div id="mechanism-order">${orderMarkup(state,p)}</div>`:''}</section>`;
}
export function orderMarkup(state,p){return `<ol class="mechanism-order">${mechanismOrder(state,p).map((name,i)=>`<li><code>${name}</code><span><button class="icon-button" data-neighbour="move-step" data-id="${p.id}" data-index="${i}" data-direction="-1" aria-label="Move ${name} earlier" ${i===0||state.neighbours.completed.includes(p.id)?'disabled':''}>↑</button><button class="icon-button" data-neighbour="move-step" data-id="${p.id}" data-index="${i}" data-direction="1" aria-label="Move ${name} later" ${i===p.order.length-1||state.neighbours.completed.includes(p.id)?'disabled':''}>↓</button></span></li>`).join('')}</ol><p role="status">${mechanismReady(state,p)?'Clean, repeat, then play. The parts are ready to work together.':'Put the three jobs in order before running your repair.'}</p>`;}
export function renderDiscoveries(state,pet){
  return `<section class="neighbours-root neighbours-world" data-view="discoveries"><header class="court-heading"><div><p class="eyebrow">SMALL SECRETS, SHARED WITH ${esc(pet.name).toUpperCase()}</p><h1>A curious companion</h1><p>Every companion can find every story. There is no hurry.</p></div><a class="button outline" href="#village">Back to the village</a></header><div class="court-stage"><div class="court-frame discovery-frame"><img class="neighbour-backdrop" src="assets/hearthwick-evening.png" alt="The familiar village paths, where your companion has noticed small clues">${discoveries.map((d,i)=>`<button class="discovery-sign discovery-sign-${i}" data-neighbour="discovery" data-id="${d.id}" style="left:${d.x/10}%;top:${d.y/6.5}%"><span>${icon(state.neighbours.completed.includes(d.id)?'check':'paw')}</span><strong>${state.neighbours.found.includes(d.id)?d.title:'A curious little clue'}</strong><small>${state.neighbours.completed.includes(d.id)?'A memory brought home':state.neighbours.found.includes(d.id)?'Something found together':'Follow your companion'}</small></button>`).join('')}<span class="discovery-party">${characterSprite('traveler','',state.wardrobe)}<span class="court-pet">${sprite(pet.id)}</span></span></div></div><div class="neighbour-bottom"><p>${state.neighbours.found.length}/3 clues found · ${discoveryProjects.filter(p=>state.neighbours.completed.includes(p.id)).length}/3 stories helped</p>${btn('discovery-book','Open our discoveries')}</div></section>`;
}
export function discoveryMarkup(state,id,pet){
  const d=discoveries.find(x=>x.id===id),p=discoveryProjects.find(x=>x.id===id),found=state.neighbours.found.includes(id),done=state.neighbours.completed.includes(id);
  return `${top('YOUR COMPANION NOTICES SOMETHING')}<div class="discovery-intro">${sprite(pet.id)}<div><h2>${found?d.title:'A little detour with '+esc(pet.name)}</h2><p>${d.hint}</p></div></div>${found?`<div class="apprentice-intro">${characterPortrait(d.npc,'community-portrait')}<p>${d.found}</p></div>${done?`<blockquote class="neighbour-memory">${p.outcome}</blockquote>${btn('use','Revisit what we made',id)}`:`<p>${neighbourUnlocked(state,p)?'A small Python project can help this story find its way home.':lockReason(state,p)}</p>${btn('project','Lend a little help',id)}`}`:`<p>Take a walk near the clue. ${esc(pet.name)} will notice it for you. You can walk with the keyboard or let your companion lead you along the path.</p>`}<div class="community-actions">${btn('follow-discovery',found?'Visit the place again':'Follow my companion',id)}${btn('discovery-book','Our discoveries')}</div>`;
}
export function discoveryBook(state,pet){return `${top('THINGS WE FOUND TOGETHER')}<h2>${esc(pet.name)} knows a few little detours.</h2><p>Nothing here needs a particular pet, a purchase, or a daily visit. Found clues stay with you when you change companions.</p><ol class="neighbour-project-list">${discoveries.map(d=>`<li><span class="lesson-knot">${icon(state.neighbours.completed.includes(d.id)?'check':'paw')}</span><div><strong>${state.neighbours.found.includes(d.id)?d.title:'An unexplored clue'}</strong><small>${d.hint}</small></div>${btn('discovery',state.neighbours.found.includes(d.id)?'Remember':'Follow',d.id)}</li>`).join('')}</ol>`;}
export function clockReport(p,r){
  if(p.kind==='discovery'){
    const points=p.id==='discovery-path'&&Array.isArray(r)?r:[];
    const path=points.length&&points.length<100&&points.every(v=>Array.isArray(v)&&v.length===2&&v.every(Number.isFinite))?`<svg class="listening-path" viewBox="0 0 300 180" role="img" aria-label="Your Python path to the listening bench"><path d="${points.map(([x,y],i)=>`${i?'L':'M'}${60+x*40},${155-y*40}`).join(' ')}" fill="none" stroke="#798c64" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>${points.map(([x,y])=>`<circle cx="${60+x*40}" cy="${155-y*40}" r="5" fill="#c8a368"/>`).join('')}<text x="150" y="22" fill="#73563b" font-size="13">The listening bench</text></svg>`:'';
    return `<div class="working-round">${path}<h3>A memory brought home</h3><pre>${esc(JSON.stringify(r,null,2))}</pre><p>${p.outcome}</p></div>`;
  }
  return `<div class="working-round mechanism-performance">${mechanismArt(p,true,'performance')}<div><h3>Working again</h3><pre>${esc(JSON.stringify(r,null,2))}</pre><p>${p.outcome}</p>${p.object==='music'?`${btn('listen','Listen to your melody')}${btn('quiet','Stop sound')}<p class="neighbour-note">Sound starts only when you choose to listen. It stops when you close this activity.</p>`:''}</div></div>`;
}
// Deliberate playback only. All oscillators are bounded and stopped on leaving,
// losing focus, hiding the page, or asking for quiet; no audio downloads.
export function createMusicPlayer({win=window,doc=document}={}){
  let context=null,nodes=[];
  const stop=()=>{for(const node of nodes){try{node.stop();}catch{}}nodes=[];if(context){const old=context;context=null;old.close()?.catch?.(()=>{});}};
  const hidden=()=>{if(doc.hidden)stop();};
  win.addEventListener('blur',stop);doc.addEventListener('visibilitychange',hidden);
  return {play(notes){stop();const frequencies={C:261.63,D:293.66,E:329.63,F:349.23,G:392,A:440,B:493.88};if(!Array.isArray(notes)||!notes.length||notes.length>32||notes.some(n=>!Object.hasOwn(frequencies,n)))return false;
    const Audio=win.AudioContext||win.webkitAudioContext;if(!Audio)return false;
    try{context=new Audio();context.resume()?.catch?.(()=>{});const now=context.currentTime;
      notes.forEach((note,i)=>{const oscillator=context.createOscillator(),gain=context.createGain(),start=now+i*.3;oscillator.type='sine';oscillator.frequency.value=frequencies[note];gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.055,start+.015);gain.gain.exponentialRampToValueAtTime(.001,start+.27);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+.29);nodes.push(oscillator);});return true;
    }catch{stop();return false;}},stop,dispose(){stop();win.removeEventListener('blur',stop);doc.removeEventListener('visibilitychange',hidden);}};
}
